import numpy as np

# Load files from injected 'files' list
t127_data = None
pmma_refs = []

for f in files:
    if f['filename'] == 'T127.csv':
        t127_data = {
            'x': np.array(f['table']['raman_shift_cm-1']),
            'y': np.array(f['table']['intensity'])
        }
    elif f['filename'] == 'reference_library.csv':
        materials = np.array(f['table']['material'])
        spec_ids = np.array(f['table']['spectrum_id'])
        shifts = np.array(f['table']['raman_shift_cm-1'])
        intensities = np.array(f['table']['intensity'])

        mask = np.char.upper(materials.astype(str)) == 'PMMA'
        if np.any(mask):
            unique_ids = np.unique(spec_ids[mask])
            for uid in unique_ids:
                uid_mask = (spec_ids == uid)
                pmma_refs.append({
                    'id': uid,
                    'x': shifts[uid_mask],
                    'y': intensities[uid_mask]
                })

if t127_data is None or not pmma_refs:
    print("Error: Missing data.")
else:
    x_sample = t127_data['x']
    y_sample = t127_data['y']
    sample_map = dict(zip(x_sample, y_sample))

    for ref in pmma_refs:
        common_x = np.intersect1d(x_sample, ref['x'])
        ref_map = dict(zip(ref['x'], ref['y']))

        v_sample = np.array([sample_map[val] for val in common_x])
        v_ref = np.array([ref_map[val] for val in common_x])

        sim = np.dot(v_sample, v_ref) / (np.linalg.norm(v_sample) * np.linalg.norm(v_ref))
        print(f"Similarity with {ref['id']}: {sim}")
